from collections import deque

def bfs(graph, start_node):
    # graph is a dictionary mapping nodes to lists of neighbors
    # Example: {0: [1, 2], 1: [0, 3], 2: [0], 3: [1]}
    visited = set()
    queue = deque([start_node])
    visited.add(start_node)
    result = []

    while queue:
        node = queue.popleft()
        result.append(node)
        for neighbor in graph.get(node, []):
            if neighbor not in visited:
                visited.add(neighbor)
                queue.append(neighbor)
    return result

import heapq

def dijkstra(graph, start_node, n):
    # graph is {node: [(neighbor, weight)]}
    distances = {i: float('inf') for i in range(n)}
    distances[start_node] = 0
    pq = [(0, start_node)]

    while pq:
        curr_dist, u = heapq.heappop(pq)
        if curr_dist > distances[u]: continue
        for v, weight in graph.get(u, []):
            if distances[u] + weight < distances[v]:
                distances[v] = distances[u] + weight
                heapq.heappush(pq, (distances[v], v))
    return distances

def has_cycle(n, edges):
    adj = [[] for _ in range(n)]
    for u, v in edges: adj[u].append(v)

    visited = [0] * n # 0=unvisited, 1=visiting, 2=visited

    def dfs(u):
        if visited[u] == 1: return True
        if visited[u] == 2: return False
        visited[u] = 1
        for v in adj[u]:
            if dfs(v): return True
        visited[u] = 2
        return False

    for i in range(n):
        if dfs(i): return True
    return False

def count_components(n, edges):
    adj = [[] for _ in range(n)]
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)

    visited = [False] * n
    count = 0

    def dfs(u):
        visited[u] = True
        for v in adj[u]:
            if not visited[v]: dfs(v)

    for i in range(n):
        if not visited[i]:
            count += 1
            dfs(i)
    return count

from collections import deque

def topo_sort(n, edges):
    adj = [[] for _ in range(n)]
    indegree = [0] * n
    for u, v in edges:
        adj[u].append(v)
        indegree[v] += 1

    queue = deque([i for i in range(n) if indegree[i] == 0])
    result = []

    while queue:
        u = queue.popleft()
        result.append(u)
        for v in adj[u]:
            indegree[v] -= 1
            if indegree[v] == 0: queue.append(v)

    return result if len(result) == n else []
